const output = $input.item.json.output;
let workflow;
try {
  const match = output.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (match) {
    workflow = JSON.parse(match[1].trim());
  } else {
    const startIdx = output.indexOf('{');
    const endIdx = output.lastIndexOf('}');
    if (startIdx >= 0 && endIdx > startIdx) {
      workflow = JSON.parse(output.slice(startIdx, endIdx + 1));
    } else {
      workflow = JSON.parse(output);
    }
  }
} catch(e) {
  workflow = {
    name: "Fallback Workflow",
    nodes: [{
      id: "manual-trigger",
      name: "Manual Trigger",
      type: "n8n-nodes-base.manualTrigger",
      typeVersion: 1,
      position: [240, 300],
      parameters: {}
    }],
    connections: {},
    settings: {executionOrder: "v1"},
    staticData: null
  };
}
if (!workflow.settings) workflow.settings = {executionOrder: "v1"};
if (!workflow.staticData) workflow.staticData = null;
if (!workflow.connections) workflow.connections = {};
return {json: {workflow}};

