} catch(e) {
  workflow = $('Parse JSON').item.json.workflow;
}
if (!workflow.settings) workflow.settings = {executionOrder: "v1"};
if (!workflow.staticData) workflow.staticData = null;
return {json: {workflow, workflowJson: JSON.stringify(workflow)}};

// Get node essentials from n8n's built-in node registry
const nodeType = ($input.item.json.nodeType || $input.item.json.query || '').replace(/^n8n-/, '');

if (!nodeType) {
  return { json: { error: 'nodeType parameter required' } };
}

// Common node configurations based on n8n standards
const nodeConfigs = {
  'nodes-base.manualTrigger': {
    type: 'n8n-nodes-base.manualTrigger',
    typeVersion: 1,
    parameters: {}
  },
  'nodes-base.webhook': {
    type: 'n8n-nodes-base.webhook',
    typeVersion: 2,
    parameters: {
      path: '',
      httpMethod: 'POST',
      responseMode: 'onReceived'
    }
  },
  'nodes-base.httpRequest': {
    type: 'n8n-nodes-base.httpRequest',
    typeVersion: 4.2,
    parameters: {
      method: 'GET',
      url: ''
    }
  },
  'nodes-base.set': {
    type: 'n8n-nodes-base.set',
    typeVersion: 3.4,
    parameters: {
      assignments: { assignments: [] }
    }
  },
  'nodes-base.code': {
    type: 'n8n-nodes-base.code',
    typeVersion: 2,
    parameters: {
      jsCode: ''
    }
  },
  'nodes-base.if': {
    type: 'n8n-nodes-base.if',
    typeVersion: 2,
    parameters: {
      conditions: {}
    }
  },
  'nodes-base.scheduleTrigger': {
    type: 'n8n-nodes-base.scheduleTrigger',
    typeVersion: 1.2,
    parameters: {
      rule: {}
    }
  }
};

const config = nodeConfigs[nodeType] || {
  type: `n8n-${nodeType}`,
  typeVersion: 1,
  parameters: {}
};

return {
  json: {
    nodeType: config.type,
    typeVersion: config.typeVersion,
    requiredParameters: config.parameters,
    usage: `Use this configuration: ${JSON.stringify(config)}`
  }
};
